 src:"#include \"common.h\"\n\nint main(void)\n{\n  HAL_Init();\n  SystemClock_Config();\n  LedInit();\n\n  // PC13 là nút B1. Board có điện trở kéo lên nên nhả = 1, nhấn = 0\n  GPIO_InitTypeDef g = {0};\n  __HAL_RCC_GPIOC_CLK_ENABLE();\n  g.Pin = GPIO_PIN_13;\n  g.Mode = GPIO_MODE_INPUT;\n  HAL_GPIO_Init(GPIOC, &g);\n\n  while (1)\n  {\n    if (HAL_GPIO_ReadPin(GPIOC, GPIO_PIN_13) == GPIO_PIN_RESET)\n      HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_SET);    // Đang nhấn: LED sáng\n    else\n      HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_RESET);  // Đã nhả: LED tắt\n  }\n}\n",
