 src:"#include \"common.h\"\n#include \"FreeRTOS.h\"\n#include \"task.h\"\n#include \"semphr.h\"\n\nstatic SemaphoreHandle_t uart_lock;  // Hai tác vụ dùng chung UART nên phải khóa\n\n// Tác vụ A, ưu tiên cao: đảo LED và in mỗi 100 ms\nstatic void TaskA(void *arg)\n{\n  int n = 0;\n  for (;;)\n  {\n    HAL_GPIO_TogglePin(GPIOA, GPIO_PIN_5);\n    xSemaphoreTake(uart_lock, portMAX_DELAY);\n    printf(\"A%d\\r\\n\", n++);\n    xSemaphoreGive(uart_lock);\n    vTaskDelay(pdMS_TO_TICKS(100));\n  }\n}\n\n// Tác vụ B, ưu tiên thấp: in mỗi 250 ms\nstatic void TaskB(void *arg)\n{\n  int n = 0;\n  for (;;)\n  {\n    xSemaphoreTake(uart_lock, portMAX_DELAY);\n    printf(\"    B%d\\r\\n\", n++);\n    xSemaphoreGive(uart_lock);\n    vTaskDelay(pdMS_TO_TICKS(250));\n  }\n}\n\nint main(void)\n{\n  HAL_Init();\n  SystemClock_Config();\n  LedInit();\n  MX_USART2_Init();\n\n  uart_lock = xSemaphoreCreateMutex();\n  xTaskCreate(TaskA, \"A\", 256, NULL, 2, NULL);\n  xTaskCreate(TaskB, \"B\", 256, NULL, 1, NULL);\n  vTaskStartScheduler();  // Từ đây FreeRTOS chia CPU cho hai tác vụ\n\n  while (1) { }\n}\n",
 b:'',
